package com.facultyavailability.faculty_availability.service;
import org.springframework.boot.CommandLineRunner; import org.springframework.context.annotation.Bean; import org.springframework.context.annotation.Configuration; import org.springframework.security.crypto.password.PasswordEncoder; import com.facultyavailability.faculty_availability.entity.AppUser; import com.facultyavailability.faculty_availability.repository.AppUserRepository;
@Configuration public class AdminInitializer { @Bean CommandLineRunner adminSeed(AppUserRepository repo,PasswordEncoder encoder){return args->{String email=System.getenv("FACULTY_ADMIN_EMAIL"),password=System.getenv("FACULTY_ADMIN_PASSWORD");if(email!=null&&!email.isBlank()&&password!=null&&password.length()>=8&&!repo.existsByEmailIgnoreCase(email)){AppUser a=new AppUser();a.setName("System Administrator");a.setEmail(email.toLowerCase());a.setPassword(encoder.encode(password));a.setRole("ADMIN");repo.save(a);}};} }
